declare namespace SigApi {
    interface Font {
        /**
         * Returns the font size
         * 
         * @returns {number}
         */
        getSize(): number
        /**
         * Returns the font name
         * 
         * @returns {string}
         */
        getName(): string
        /**
         * Returns the font family
         * 
         * @returns {string}
         */
        getFontFamily(): string
        /**
         * Returns the font italic setting
         * 
         * @returns {boolean}
         */
        isItalic(): boolean
        /**
         * Returns the font bold setting
         * 
         * @returns {boolean}
         */
        isBold(): boolean
        /**
         * Returns the font underline setting
         * 
         * @returns {boolean}
         */
        isUnderline(): boolean
    }
}
